/** @jsxImportSource kerfjs */
import { delegate } from 'kerfjs';
import { PageHeader } from '@kerfjs/ui/page-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import '@kerfjs/ui/layout.css';
import './list-workspace.css';

export type Task = { id: string; title: string; owner: string; status: string };
export function createListWorkspace(
  load: (signal: AbortSignal) => Promise<Task[]>,
  createTask: () => void,
) {
  // null means no successful response yet; [] means a successful empty result.
  let items: Task[] | null = null;
  let pending = false;
  let error: string | null = null;
  let controller: AbortController | undefined;
  let generation = 0;
  let disposed = false;
  let invalidate = () => {};
  const state = () => pending ? (items === null ? 'loading' : 'refreshing')
    : error ? 'error' : items?.length ? 'populated' : 'empty';
  const render = () => <section class="task-workspace kui-layout" data-state={state()}>
    <PageHeader title="Release tasks" action={<div class="kui-control-cluster">
      <button class="task-button" type="button" data-action="tasks.refresh" disabled={pending}>Refresh</button>
      <button class="task-button" type="button" data-action="tasks.create">New task</button>
    </div>} />
    <div class="task-workspace-body kui-scroll-owner kui-pane-body kui-section-stack" tabindex="0" aria-label="Release task content">
      {error && <StateBanner tone="danger" urgency="alert"
        title={items === null ? 'Tasks could not be loaded' : 'Tasks could not be refreshed'}
        detail={error}
        action={<button class="task-button" type="button" data-action="tasks.retry" disabled={pending}>{pending ? 'Retrying…' : 'Retry'}</button>} />}
      {pending && items !== null && <StateBanner tone="info" title="Refreshing tasks"
        detail="Showing the last successful results while checking for updates."
        action={<LoadingSpinner label="Refreshing release tasks" />} />}
      <div aria-busy={pending ? 'true' : 'false'}>
        {items === null
          ? pending
            ? <EmptyState busy title="Loading release tasks" detail="Your tasks will appear here when the request finishes." />
            : <EmptyState title="Tasks unavailable" detail="Use Retry above to load this workspace." />
          : items.length === 0
            ? <EmptyState title="No release tasks" detail="Create the first task for this milestone."
                action={<button class="task-button" type="button" data-action="tasks.create">Create task</button>} />
            : <ul class="task-list" aria-label="Release tasks">{items.map(item => <li data-task-id={item.id}>
                <strong>{item.title}</strong>
                <span class="kui-inline-metadata"><span>Status: {item.status}</span><span>Owner: {item.owner}</span></span>
              </li>)}</ul>}
      </div>
      <p class="task-result-status" role="status" aria-live="polite">{!pending && !error && items !== null ? items.length + ' tasks loaded.' : ''}</p>
    </div>
  </section>;
  async function refresh() {
    const request = ++generation;
    controller?.abort();
    controller = new AbortController();
    pending = true;
    // Retain an important error throughout retry, until a successful response.
    invalidate();
    try {
      const result = await load(controller.signal);
      if (disposed || request !== generation) return;
      items = result;
      error = null;
    } catch {
      if (disposed || request !== generation) return;
      error = items === null
        ? 'The connection failed. Your workspace settings are preserved; please try again.'
        : 'The connection failed. The last successful results remain visible; please try again.';
    } finally {
      if (!disposed && request === generation) { pending = false; invalidate(); }
    }
  }
  function connect(root: HTMLElement, rerender: () => void) {
    invalidate = rerender;
    const dispose = delegate(root, 'click', '[data-action]', (_event, element) => {
      const action = element.getAttribute('data-action');
      if (action === 'tasks.refresh' || action === 'tasks.retry') void refresh();
      if (action === 'tasks.create') createTask();
    });
    void refresh();
    return () => { disposed = true; generation++; controller?.abort(); dispose(); invalidate = () => {}; };
  }
  return { render, connect, refresh };
}

