.task-workspace { display:grid; height:100%; min-height:0; min-width:0; grid-template-rows:auto minmax(0,1fr); color:var(--kui-color-text); background:var(--kui-color-surface); }
.task-workspace-body { min-height:0; min-width:0; }
.task-list { display:grid; padding:0; margin:0; list-style:none; }
.task-list li { display:grid; gap:var(--kui-layout-metadata-gap); padding-block:var(--kui-space-s); border-block-end:1px solid var(--kui-color-border); overflow-wrap:anywhere; }
.task-list .kui-inline-metadata { color:var(--kui-color-text-quiet); flex-wrap:wrap; }
.task-button { font:inherit; min-height:2.75rem; padding:var(--kui-space-xs) var(--kui-space-s); border:1px solid var(--kui-color-border); border-radius:var(--kui-radius-m); background:var(--kui-color-surface); color:var(--kui-color-text); }
.task-workspace :focus-visible { outline:var(--kui-focus-ring); outline-offset:2px; }
.task-result-status { margin:0; color:var(--kui-color-text-quiet); }
@media(max-width:48rem) { .task-workspace .kui-page-header { flex-direction:column; align-items:stretch; } }
